CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, telegram_id TEXT UNIQUE NOT NULL, username TEXT, first_name TEXT, balance BIGINT NOT NULL DEFAULT 0, last_daily_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tasks (id BIGSERIAL PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', channel_url TEXT, reward BIGINT NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS task_completions (user_id BIGINT REFERENCES users(id), task_id BIGINT REFERENCES tasks(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(user_id,task_id));
CREATE TABLE IF NOT EXISTS transactions (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id), amount BIGINT NOT NULL, type TEXT NOT NULL, meta JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS games (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id), bet BIGINT NOT NULL, mines INT NOT NULL, state JSONB NOT NULL, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS shop_packages (id BIGSERIAL PRIMARY KEY, leaves BIGINT NOT NULL, stars INT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
INSERT INTO shop_packages(leaves,stars) SELECT 2000,1 WHERE NOT EXISTS (SELECT 1 FROM shop_packages);
